mapper.select:
/*selectMasterMdCmCmsItemExcelUploadBeforeList*/ SELECT C.CMS_CATLG_ID , DECODE(C.STATUS,'D','미사용','사용') AS STATUS_BEFORE /* 상품상태 */ , C.DESCRIPTION_LOC AS DESCRIPTION_BEFORE /* 품목명 */ , C.MODEL_INFO AS MODEL_BEFORE /* 모델번호 */ , C.SPECIFICATION AS SPEC_BEFORE /* 규격 */ , C.MAKER_NAME AS MAKER_BEFORE /* 제조사명 */ , C.MAKER_CODE AS MAKER_CODE_BEFORE /* 제조사코드 — 반영 축 */ , (SELECT MD.TEXT2 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M001' AND MD.CODE = C.ORIGIN_CODE) AS ORIGIN_BEFORE /* 원산지명 */ , C.ORIGIN_CODE AS ORIGIN_CODE_BEFORE /* 원산지코드 — 반영 축 */ , C.ORDER_MEASURE AS MEASURE_BEFORE /* 단위 */ , DECODE(C.ITEM_GUBUN,'G','표준품','비표준품') AS ITEM_GUBUN_BEFORE /* 상품구분 */ , (SELECT MD.TEXT1 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M181' AND MD.CODE = C.TR_HANDLE_TYPE) AS TR_BEFORE /* TR취급가능여부 */
, T.ATTB1_NM AS ATTR1_NM , T.ATTB2_NM AS ATTR2_NM , T.ATTB3_NM AS ATTR3_NM , T.ATTB4_NM AS ATTR4_NM , T.ATTB5_NM AS ATTR5_NM , T.ATTB6_NM AS ATTR6_NM , T.ATTB7_NM AS ATTR7_NM , T.ATTB8_NM AS ATTR8_NM , T.ATTB9_NM AS ATTR9_NM , T.ATTB10_NM AS ATTR10_NM, T.ATTB11_NM AS ATTR11_NM, T.ATTB12_NM AS ATTR12_NM , T.ATTB13_NM AS ATTR13_NM , C.ATTB1_NM AS ATTR1_BVAL , C.ATTB2_NM AS ATTR2_BVAL , C.ATTB3_NM AS ATTR3_BVAL , C.ATTB4_NM AS ATTR4_BVAL , C.ATTB5_NM AS ATTR5_BVAL , C.ATTB6_NM AS ATTR6_BVAL , C.ATTB7_NM AS ATTR7_BVAL , C.ATTB8_NM AS ATTR8_BVAL , C.ATTB9_NM AS ATTR9_BVAL , C.ATTB10_NM AS ATTR10_BVAL, C.ATTB11_NM AS ATTR11_BVAL, C.ATTB12_NM AS ATTR12_BVAL , C.ATTB13_NM AS ATTR13_BVAL FROM CMSCATLG C , CMSCATTR T WHERE C.CMS_CATEG_ID = T.CMS_CATEG_ID(+) AND T.STATUS(+) <> 'D' AND C.CMS_CATLG_ID IN
#{item}

