/*selectMasterMdCmCmsItemBasePriceBeforeList*/ SELECT C.CMS_CATLG_ID , C.DESCRIPTION_LOC AS DESCRIPTION_LOC /* 품목명 */ , C.MODEL_INFO AS MODEL_INFO /* 모델번호 */ , C.SPECIFICATION AS SPECIFICATION /* 규격 */ , C.MAKER_NAME AS MAKER_NAME /* 제조사 */ , (SELECT MD.TEXT2 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M001' AND MD.CODE = C.ORIGIN_CODE) AS ORIGIN_NAME /* 원산지 */ , C.ORDER_MEASURE AS MEASURE /* 단위 */
, TRIM(TO_CHAR(C.BASE_PRICE)) AS PRICE_BEFORE /* 기준가(원값, 문자열) */ , (SELECT MD.TEXT1 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M183' AND MD.CODE = C.BASE_PRICE_TYPE) AS PRICE_TYPE_BEFORE /* 기준가유형(명칭) */ FROM CMSCATLG C WHERE C.CMS_CATLG_ID IN
#{item}
